import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import boto3


def compare_cloudwatch_metric_values(
    namespace: str,
    metric_name: str,
    resource_a_dimensions: List[Dict[str, str]],
    resource_b_dimensions: List[Dict[str, str]],
    stat: str = "Average",
    period: int = 300,
    window_minutes: int = 60,
    region_name: Optional[str] = None,
    unit: Optional[str] = None,
) -> Dict[str, Any]:
    cloudwatch = boto3.client(
        "cloudwatch",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
    )

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(minutes=window_minutes)

    metric_data_queries = [
        {
            "Id": "resourcea",
            "MetricStat": {
                "Metric": {
                    "Namespace": namespace,
                    "MetricName": metric_name,
                    "Dimensions": resource_a_dimensions,
                },
                "Period": period,
                "Stat": stat,
                **({"Unit": unit} if unit else {}),
            },
            "ReturnData": True,
        },
        {
            "Id": "resourceb",
            "MetricStat": {
                "Metric": {
                    "Namespace": namespace,
                    "MetricName": metric_name,
                    "Dimensions": resource_b_dimensions,
                },
                "Period": period,
                "Stat": stat,
                **({"Unit": unit} if unit else {}),
            },
            "ReturnData": True,
        },
    ]

    response = cloudwatch.get_metric_data(
        MetricDataQueries=metric_data_queries,
        StartTime=start_time,
        EndTime=end_time,
        ScanBy="TimestampAscending",
    )

    results_by_id = {r["Id"]: r for r in response.get("MetricDataResults", [])}

    def normalize(result: Dict[str, Any]) -> Dict[str, Any]:
        timestamps = result.get("Timestamps", [])
        values = result.get("Values", [])
        points = sorted(
            [
                {"timestamp": ts.isoformat(), "value": val}
                for ts, val in zip(timestamps, values)
            ],
            key=lambda x: x["timestamp"],
        )
        series_values = [p["value"] for p in points]
        latest_value = points[-1]["value"] if points else None
        average_value = sum(series_values) / len(series_values) if series_values else None
        sum_value = sum(series_values) if series_values else None
        min_value = min(series_values) if series_values else None
        max_value = max(series_values) if series_values else None
        return {
            "id": result.get("Id"),
            "label": result.get("Label"),
            "status_code": result.get("StatusCode"),
            "messages": result.get("Messages", []),
            "points": points,
            "summary": {
                "latest": latest_value,
                "average": average_value,
                "sum": sum_value,
                "min": min_value,
                "max": max_value,
                "count": len(series_values),
            },
        }

    a = normalize(results_by_id.get("resourcea", {}))
    b = normalize(results_by_id.get("resourceb", {}))

    def delta(x: Optional[float], y: Optional[float]) -> Optional[float]:
        if x is None or y is None:
            return None
        return x - y

    def pct_change(x: Optional[float], y: Optional[float]) -> Optional[float]:
        if x is None or y in (None, 0):
            return None
        return ((x - y) / y) * 100.0

    return {
        "provider": "amazon_cloudwatch",
        "metric": {
            "namespace": namespace,
            "name": metric_name,
            "stat": stat,
            "period_seconds": period,
            "unit": unit,
        },
        "window": {
            "start": start_time.isoformat(),
            "end": end_time.isoformat(),
            "minutes": window_minutes,
        },
        "resource_a": {
            "dimensions": resource_a_dimensions,
            "result": a,
        },
        "resource_b": {
            "dimensions": resource_b_dimensions,
            "result": b,
        },
        "comparison": {
            "latest_delta": delta(a["summary"]["latest"], b["summary"]["latest"]),
            "latest_pct_change_vs_b": pct_change(a["summary"]["latest"], b["summary"]["latest"]),
            "average_delta": delta(a["summary"]["average"], b["summary"]["average"]),
            "average_pct_change_vs_b": pct_change(a["summary"]["average"], b["summary"]["average"]),
            "sum_delta": delta(a["summary"]["sum"], b["summary"]["sum"]),
            "sum_pct_change_vs_b": pct_change(a["summary"]["sum"], b["summary"]["sum"]),
        },
    }
